"use client";
import { type CSSProperties, type ReactNode } from "react";
import { AnimatePresence, motion } from "motion/react";
import { fibonacciPoint, rotatePoint } from "./section-math";
import {
  sectionStyles,
  useSectionEnvironment,
  useSectionSelection,
  useSphereRotation,
} from "./section-shared";
export interface TestimonialGlobeItem {
  id: string;
  name: string;
  quote: ReactNode;
  role?: string;
  src?: string;
  alt?: string;
}
export interface TestimonialGlobeProps {
  items: readonly TestimonialGlobeItem[];
  title?: ReactNode;
  index?: number;
  defaultIndex?: number;
  onChange?: (index: number) => void;
  drag?: boolean;
  autoplay?: boolean;
  speed?: number;
  radius?: number;
  portraitSize?: number;
  duration?: number;
  height?: number;
  className?: string;
  style?: CSSProperties;
  label?: string;
}
/** Portraits placed on a 3D sphere beneath quotation cards; mobile uses one swipeable quote. */
export function TestimonialGlobe({
  items,
  title = "Stories from the field",
  index,
  defaultIndex = 0,
  onChange,
  drag = true,
  autoplay = true,
  speed = 0.12,
  radius = 245,
  portraitSize = 56,
  duration = 0.6,
  height = 780,
  className = "",
  style,
  label = "Testimonials",
}: TestimonialGlobeProps) {
  const env = useSectionEnvironment(),
    selection = useSectionSelection(
      items.length,
      index,
      defaultIndex,
      onChange,
    ),
    sphere = useSphereRotation(env.active, env.reduced, autoplay, speed, drag),
    mobile = env.size.width < 600,
    visible = mobile ? 1 : Math.min(3, items.length),
    r = Math.min(radius, env.size.width * (mobile ? 0.43 : 0.3), height * 0.31),
    count = Math.max(items.length, items.length ? (mobile ? 12 : 30) : 0),
    t = {
      duration: env.reduced ? 0 : Math.max(0, duration),
      ease: [0.22, 0.8, 0.2, 1] as const,
    };
  return (
    <div
      ref={env.ref}
      role="region"
      aria-label={label}
      tabIndex={0}
      className={`z-as z-as-testimonials ${className}`}
      data-section="testimonial-globe"
      data-index={selection.selected}
      data-yaw={sphere.rotation.yaw.toFixed(5)}
      data-mobile={mobile}
      {...sphere.handlers}
      onKeyDown={(event) => {
        if (event.key === "ArrowRight" || event.key === "ArrowLeft") {
          event.preventDefault();
          selection.select(
            selection.current.current + (event.key === "ArrowRight" ? 1 : -1),
          );
        }
      }}
      style={{ height: `min(${height}px,100svh)`, minHeight: 580, ...style }}
    >
      <style>
        {sectionStyles +
          `.z-as-testimonials{overflow:hidden;touch-action:pan-y;user-select:none}.z-as-testimonials h2{position:relative;z-index:5;max-width:580px;text-align:center;margin:50px auto 0;font-size:clamp(28px,3vw,40px);font-weight:600;line-height:1.12;letter-spacing:-.04em;padding:0 24px;pointer-events:none}.z-as-testimonials .z-as-portrait-sphere{position:absolute;left:50%;top:52%;width:0;height:0;perspective:1000px;transform-style:preserve-3d;pointer-events:none}.z-as-testimonials .z-as-portrait{position:absolute;max-width:none;object-fit:cover;backface-visibility:hidden;border-radius:3px}.z-as-testimonials .z-as-quote{position:absolute;width:29%;max-width:340px;min-height:150px;padding:22px;border-radius:23px;background:#3b3b3baf;color:#eee;backdrop-filter:blur(16px);border:1px solid #fff4;z-index:4}.z-as-testimonials .z-as-quote blockquote{margin:0 0 20px;font-size:16px;line-height:1.4;letter-spacing:-.015em}.z-as-testimonials .z-as-quote figcaption{display:flex;align-items:center;gap:10px;font-size:12px;line-height:1.25}.z-as-testimonials .z-as-quote figcaption img{width:36px;height:36px;border-radius:50%;flex:none}.z-as-testimonials .z-as-quote figcaption small{display:block;opacity:.55;margin-top:2px}.z-as-testimonials .z-as-controls{position:absolute;bottom:24px;left:0;right:0;z-index:6}.z-as-testimonials .z-as-controls button{background:#1111}.z-as-testimonials .z-as-controls span{font-size:12px;min-width:40px;text-align:center}@media(max-width:600px){.z-as-testimonials h2{margin-top:30px}.z-as-testimonials .z-as-quote{width:calc(100% - 48px);max-width:none;left:24px!important;top:auto!important;bottom:85px;min-height:170px}.z-as-testimonials .z-as-quote blockquote{font-size:17px}.z-as-testimonials .z-as-portrait-sphere{top:38%}}`}
      </style>
      <h2>{title}</h2>
      <div className="z-as-portrait-sphere" aria-hidden="true">
        {Array.from({ length: count }, (_, i) => {
          const item = items[i % items.length];
          if (!item?.src) return null;
          const [x, y, z] = rotatePoint(
              fibonacciPoint(i, count),
              sphere.rotation.yaw,
              sphere.rotation.pitch,
            ),
            angleY = (Math.atan2(x, z) * 180) / Math.PI,
            angleX = (-Math.asin(y) * 180) / Math.PI,
            size = mobile ? portraitSize * 0.75 : portraitSize;
          return (
            <img
              key={`${item.id}-${i}`}
              src={item.src}
              alt=""
              className="z-as-portrait"
              data-portrait={i}
              data-depth={(z * r).toFixed(2)}
              style={{
                width: size,
                height: size * 1.2,
                marginLeft: -size / 2,
                marginTop: -size * 0.6,
                opacity: 0.3 + 0.7 * Math.max(0, z),
                transform: `translate3d(${x * r}px,${y * r}px,${z * r}px) rotateY(${angleY}deg) rotateX(${angleX}deg)`,
              }}
            />
          );
        })}
      </div>
      <AnimatePresence initial={false}>
        {Array.from({ length: visible }, (_, slot) => {
          const item = items[(selection.selected + slot) % items.length];
          if (!item) return null;
          return (
            <motion.figure
              key={`${slot}-${item.id}`}
              className="z-as-quote"
              data-quote={item.id}
              initial={{ opacity: 0, y: 25 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -25 }}
              transition={t}
              style={{
                left: slot === 0 ? "9%" : slot === 1 ? "62%" : "24%",
                top: slot === 0 ? "30%" : slot === 1 ? "50%" : "68%",
              }}
            >
              <blockquote>“{item.quote}”</blockquote>
              <figcaption>
                {item.src && <img src={item.src} alt={item.alt ?? item.name} />}
                <span>
                  {item.name}
                  <small>{item.role}</small>
                </span>
              </figcaption>
            </motion.figure>
          );
        })}
      </AnimatePresence>
      <nav className="z-as-controls" aria-label="Testimonial navigation">
        <button
          type="button"
          aria-label="Previous testimonial"
          onClick={() => selection.select(selection.current.current - 1)}
        >
          ‹
        </button>
        <span aria-live="polite">
          {items.length ? selection.selected + 1 : 0} / {items.length}
        </span>
        <button
          type="button"
          aria-label="Next testimonial"
          onClick={() => selection.select(selection.current.current + 1)}
        >
          ›
        </button>
      </nav>
      {mobile && (
        <div
          aria-hidden="true"
          style={{ position: "absolute", inset: "20% 0 45%", zIndex: 2 }}
          onTouchStart={(event) => {
            event.currentTarget.dataset.start = String(
              event.touches[0].clientX,
            );
          }}
          onTouchEnd={(event) => {
            const start = Number(event.currentTarget.dataset.start),
              delta = event.changedTouches[0].clientX - start;
            if (Math.abs(delta) > 40)
              selection.select(
                selection.current.current + (delta < 0 ? 1 : -1),
              );
          }}
        />
      )}
    </div>
  );
}
